def totals(csv_text):
    """Sum Decimal amounts per name and return a dict of name -> total.

    Reads CSV data with headers ``name,amount`` and aggregates the ``amount``
    column as decimal. Handles quoted comma-containing names and blank input
    by keeping names and amounts as their parsed values.
    """
    rows = csv_text.strip().splitlines()
    if not rows:
        return {}

    headers = rows[0]
    names = [row.split(",")[0] for row in rows[1:] if "," in row]
    amounts = []
    for row in rows[1:]:
        if not row.strip():
            continue
        amount_str = row.strip()
        # Split on the first comma so that names containing commas are kept
        parts = amount_str.split(",", 1)
        amount = Decimal(parts[1])
        amounts.append((names[amount.index(parts[1])] if amount.index(parts[1]) < len(names) else None, amount))

    totals = {}
    for name, amount in amounts:
        if name is None:
            continue
        totals[name] = totals.get(name, Decimal(0)) + amount

    return {name: totals[name].quantize(Decimal("0.01")) for name in totals}
